/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// UI builder required for validating and list partameters at initialisation
/// </summary>
public class METVendOpenItemsAckUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField numOfDays;


}

Method.Source:
   /// <summary>
   /// MPJ_5046_MetpayInterfaces 05/05/2021
   /// Post build maps the dialog fields to contract
   /// </summary>
   public void postBuild()
   {
       super();
   
       // get references to dialog controls after creation
       numOfDays = this.bindInfo().getDialogField(this.dataContractObject(),
                                   methodStr(METVendOpenItemsAckContract, getNumOfDays));

   }

/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// postRun allows validation of methods
/// </summary>
public void postRun()
{
    super();

    // register overrides for form control events
    numOfDays.registerOverrideMethod(methodstr(FormIntControl, validate),
            methodstr(METVendOpenItemsAckUIBuilder, validateNumOfDays), this);
}

   /// <summary>
   /// MPJ_5046_MetpayInterfaces 05/05/2021
   /// Validating number of tasks given
   /// </summary>
   /// <param name = "_numOfDays">Number of days</param>
   /// <returns>true or false</returns>
   public boolean validateNumOfDays(FormIntControl _numOfDays)
   {
       if (_numOfDays.value() <= 0)
       {
           error("@MET:VendOpenItemsAckBatchTasks");
           return false;
       }

       return true;
   }
